INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Marktbeobachtung nur einmalig durchgeführt wird. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Kontinuierlich nötig"}, {"text": "Ja", "correct": false, "because": "Falsche Annahme"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich, wenn ich Marktbeobachtung für eine IT-Firma plane?', 3, '[{"text": "Datenquellen", "correct": true, "because": "Bestimmen Informationen"}, {"text": "Schnellste Analyse", "correct": false, "because": "Genauigkeit zählt"}, {"text": "Bürodesign", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Bereiche umfasst die Marktbeobachtung in der IT?', 5, '[{"text": "Wettbewerber", "correct": true, "because": "Zeigt Konkurrenz"}, {"text": "Trends", "correct": true, "because": "Beeinflusst Strategie"}, {"text": "Büroausstattung", "correct": false, "because": "Kein Markt"}, {"text": "Farbschema", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Marktbeobachtung hilft Trends zu erkennen. b) Sie ist immer teuer.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kosten variieren"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich Marktbeobachtung für eine IT-Firma durchführe?', 4, '[{"text": "Kundenverhalten", "correct": false, "because": "Wichtiger Faktor"}, {"text": "Wettbewerbsdaten", "correct": false, "because": "Für Strategie nötig"}, {"text": "Bürogestaltung", "correct": true, "because": "Kein Markt"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Marktbeobachtung nur interne Daten nutzt?', 2, '[{"text": "Nein", "correct": true, "because": "Auch externe Quellen"}, {"text": "Ja", "correct": false, "because": "Zu begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit Marktbeobachtung in der IT?', 3, '[{"text": "Markttrends erkennen", "correct": true, "because": "Für Strategie"}, {"text": "Schnellste Umsetzung", "correct": false, "because": "Sekundär"}, {"text": "Weniger Daten", "correct": false, "because": "Nicht Ziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methoden nutzt die Marktbeobachtung in der IT?', 5, '[{"text": "Kundenbefragung", "correct": true, "because": "Primäre Daten"}, {"text": "Wettbewerbsanalyse", "correct": true, "because": "Sekundäre Daten"}, {"text": "Büroplanung", "correct": false, "because": "Irrelevant"}, {"text": "Farbanalyse", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Marktbeobachtung unterstützt strategische Entscheidungen. b) Sie ist nur für große Firmen. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch KMU nutzen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für Marktbeobachtung in der IT?', 4, '[{"text": "Datenquellen", "correct": false, "because": "Liefern Informationen"}, {"text": "Analysewerkzeuge", "correct": false, "because": "Verarbeiten Daten"}, {"text": "Büroausstattung", "correct": true, "because": "Kein Markt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist Marktbeobachtung dasselbe wie Marktanalyse?', 2, '[{"text": "Nein", "correct": true, "because": "Kontinuierlich vs. einmalig"}, {"text": "Ja", "correct": false, "because": "Verschiedene Zwecke"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet Marktbeobachtung in der IT?', 4, '[{"text": "Wettbewerbsvorteil", "correct": true, "because": "Frühzeitige Erkennung"}, {"text": "Trendidentifikation", "correct": true, "because": "Passt Strategie an"}, {"text": "Schnellere Projekte", "correct": false, "because": "Kein direkter Vorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Marktbeobachtung nur für Absatzmärkte gilt. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Beschaffungsmärkte"}, {"text": "Ja", "correct": false, "because": "Zu eingeschränkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Was wähle ich, um Marktbeobachtung für eine IT-Firma durchzuführen?', 3, '[{"text": "Datenanalyse-Tools", "correct": true, "because": "Verarbeiten Informationen"}, {"text": "Schnellste Software", "correct": false, "because": "Genauigkeit wichtiger"}, {"text": "Bunte Diagramme", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Marktbeobachtung nutzt externe Daten. b) Sie ist immer kostenlos.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kosten entstehen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren berücksichtige ich bei Marktbeobachtung in der IT?', 5, '[{"text": "Markttrends", "correct": true, "because": "Beeinflussen Strategie"}, {"text": "Konkurrenzaktionen", "correct": true, "because": "Für Wettbewerb"}, {"text": "Bürogröße", "correct": false, "because": "Irrelevant"}, {"text": "Farbschema", "correct": false, "because": "Ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist unwichtig, wenn ich Marktbeobachtung für eine IT-Firma plane?', 3, '[{"text": "Datenquellen", "correct": false, "because": "Liefern Informationen"}, {"text": "Analysewerkzeuge", "correct": false, "because": "Verarbeiten Daten"}, {"text": "Büroausstattung", "correct": true, "because": "Kein Markt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Nutzt Marktbeobachtung nur interne Daten?', 3, '[{"text": "Nein", "correct": true, "because": "Auch externe Quellen"}, {"text": "Ja", "correct": false, "because": "Zu begrenzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Marktbeobachtung für kleine IT-Firmen irrelevant ist?', 2, '[{"text": "Nein", "correct": true, "because": "Auch KMU profitieren"}, {"text": "Ja", "correct": false, "because": "Für alle nützlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element ist entscheidend für Marktbeobachtung in der IT?', 4, '[{"text": "Datenqualität", "correct": true, "because": "Sichert Zuverlässigkeit"}, {"text": "Schnellste Umsetzung", "correct": false, "because": "Genauigkeit zählt"}, {"text": "Büroausstattung", "correct": false, "because": "Irrelevant"}]');
